 "content": "def transform(grid):
    # The demo's color-3 horizontal bar is the motif; color-2 cells mark
    # where its central color-2 cell belongs. Build the motif from the
    # repeated 3-run and place it centered on each 2-run.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    rows = {}
    for r, row in enumerate(grid):
        cols = [c for c, v in enumerate(row) if v == 3]
        if cols:
            rows[r] = cols
    # Motif has 3-cells on a horizontal row, and a single 2 cell one row
    # below its center. This relation is demonstrated with a 6-wide bar.
    bars = []
    for r, cols in rows.items():
        lo, hi = min(cols), max(cols)
        if len(cols) == hi - lo + 1:
            bars.append((r, lo, hi))
    if not bars:
        return out
    # Repeating bars in the demo represent the template, all same color.
    # Use the longest 3-run as its width; the lower 2 is centered below.
    _, _, _ = bars[0]
    motif_w = max(hi - lo + 1 for _, lo, hi in bars)
    # Template: width of 3 bar with a 2 one row down, centered.
    # 3-run spans offsets 0..width-1; 2 is at center.
    for r, row in enumerate(grid):
        targets = [c for c, v in enumerate(row) if v == 2]
        if not targets:
            continue
        # Process contiguous color-2 runs as individual placement centers.
        runs = []
        for c in targets:
            if not runs or c > runs[-1][-1] + 1:
                runs.append([c])
            else:
                runs[-1].append(c)
        for run in runs:
            center = (run[0] + run[-1]) // 2
            start = center - (motif_w - 1) // 2
            for dc in range(motif_w):
                cc = start + dc
                if 0 <= r - 1 < h and 0 <= cc < w:
                    out[r - 1][cc] = 3
            # Preserve/paint the central 2 beneath the copied bar.
            if 0 <= center < w:
                out[r][center] = 2
    # Return the compact motif bounding box: inferred from demo output.
    cells = [(r,c) for r in range(h) for c in range(w) if out[r][c] in (2,3)]
    if not cells:
        return out
