 "content": "def transform(grid):
    """Encode the number of horizontal segments of colors 3 and 2 in 2x3."""
    counts = {3: 0, 2: 0}
    for row in grid:
        for color in (3, 2):
            active = False
            for value in row:
                if value == color:
                    if not active:
                        counts[color] += 1
                    active = True
                else:
                    active = False
    cells = [3] * counts[3] + [2] * counts[2]
    cells = (cells + [0] * 6)[:6]
    return [cells[:3], cells[3:]]
